for i, (prompt, options, answer, explanation, strategy) in enumerate(DATA, 1):
    path = ROOT / "questions/science" / f"question-science-content-ma-iv-2-{i}.json"
    item = json.loads(path.read_text())
    correct = options[ord(answer) - 65]
    target = TARGET_ANSWERS[i - 1]
    distractors = [text for option_index, text in enumerate(options) if option_index != ord(answer) - 65]
    position = ord(target) - 65
    arranged = distractors[:position] + [correct] + distractors[position:]
    item.update({"prompt": prompt, "options": [{"id": chr(65+j), "text": t} for j, t in enumerate(arranged)], "answer": {"value": target, "explanation": f"{explanation} 正確答案為選項 {target}：「{correct}」。"}, "solutionStrategy": strategy, "solutionSteps": ["圈出生物多樣性層次、保育目標、調查指標與人類行動。", "檢查是否有標準化採樣、對照、長期追蹤與利害關係人資料。", f"套用本題原理：{explanation}", f"排除只看單一指標、單次觀察或忽略社會與生態條件的選項，答案為「{correct}」（選項 {target}）。", "回查結論是否只涵蓋證據能支持的範圍，並指出仍需追蹤的條件。"], "examPatternRefs": REFS, "reviewStatus": "draft", "updatedAt": "2026-09-13"})
    path.write_text(json.dumps(item, ensure_ascii=False, indent=2) + "\n")
print(f"rewrote {len(DATA)} questions")
